use crate::*;
const fn doc(
    name: &'static str,
    summary: &'static str,
    sections: &'static [BuiltinDocumentationSection],
    examples: &'static [BuiltinExample],
) -> BuiltinDocumentation {
    BuiltinDocumentation{
        authority:BuiltinDocumentationAuthority::Catalog,title:Some(name),slug:Some(name),summary,description:summary,
        keywords:&["particle swarm","derivative free","optimization","population"],related:&["particleswarm","optimoptions","patternsearch","rng"],
        sections,examples,example_exemption:None,faqs:&[],media:&[],
        links:&[BuiltinDocumentationLink{label:"MathWorks particle-swarm contracts",target:BuiltinDocumentationLinkTarget::External("https://www.mathworks.com/help/gads/particleswarm.html")},
            BuiltinDocumentationLink{label:"MathWorks algorithm",target:BuiltinDocumentationLinkTarget::External("https://www.mathworks.com/help/gads/particle-swarm-optimization-algorithm.html")}],
        evidence:BuiltinDocumentationEvidence{
            implementation:&[BuiltinDocumentationLink{label:"Original-context swarm implementation",target:BuiltinDocumentationLinkTarget::Source("https://github.com/runmat-org/runmat/blob/main/crates/runmat-runtime/src/builtins/math/optim/particleswarm.rs")}],
            verification:&[BuiltinEvidenceReference{kind:BuiltinEvidenceKind::UnitTest,label:"Swarm dynamics, actual callbacks, bounds, public outputs and original authority",location:"builtins::math::optim::particleswarm::tests"}],
            notes:&["Source controls do not establish fresh Cargo, native, browser, provider, MATLAB or performance acceptance."],
        },
        introduced:None,status:Some(BuiltinDocumentationStatus::Partial),
    }
}
pub(super) const SOLVER:BuiltinDocumentation=doc("particleswarm",
    "Minimize a scalar objective with a genuine adaptive-neighborhood particle swarm.",
    &[
        BuiltinDocumentationSection{heading:"Forms and data",paragraphs:&[
            "Forms are particleswarm(fun,nvars), particleswarm(fun,nvars,lb,ub), particleswarm(fun,nvars,lb,ub,options), and particleswarm(problem). The scalar problem has objective, nvars, lb, ub, options, solver='particleswarm', and optional rngstate. fun is a selected function handle or scalar function name. nvars is a positive integer-valued double; problem coordinates and bounds are real full host doubles. Bounds flatten in column-major order; [] is unbounded. A scalar bound expands, while a shorter nonscalar bound leaves trailing coordinates unbounded with a warning. Inconsistent bounds return x=[], fval=[] and flag -2 without objective, custom creation, RNG or plot effects.",
            "Scalar objectives receive one 1-by-nvars row. With UseVectorized=true they receive an M-by-nvars matrix and return M actual double measurements; M can be one. The numerical comparison score accepts only finite real values. FunValCheck='on' rejects complex, Inf or NaN measurements; with 'off', undefined particles cannot win. Malformed carriers, callback errors, cancellation and provider errors remain errors, not undefined scores. An entirely undefined initial swarm cannot establish an incumbent and fails truthfully.",
            "Up to five outputs are x, fval, exitflag, output and points. x is the best actual row and fval its actual measurement, optionally improved by the hybrid. output contains iterations, funccount, message, hybridflag, rngstate and swarmObjectiveCallCount. funccount includes actual measured particle points plus the hybrid's actual reported evaluations; the separate swarm call count distinguishes vectorized batches. points.X/Fval remain the actual final swarm, not individual historical bests or a hybrid point. Reporting never calls fun again.",
        ]},
        BuiltinDocumentationSection{heading:"Algorithm and effective controls",paragraphs:&[
            "The algorithm maintains current positions, velocities and each particle's best actually measured position. A random adaptive neighborhood supplies the social target. The inertia-weighted velocity adds independent uniform personal and social components. Positions are clipped to bounds; an outward velocity at a clipped bound is reset. Successful generations lower the stall counter, restore the minimum neighborhood and adapt inertia; unsuccessful generations grow the neighborhood. This is not a local solver alias and does not certify a global minimum.",
            "SwarmSize is an integer greater than one, default min(100,10*nvars). InertiaRange is an increasing same-sign finite pair, default [0.1,1.1]. MinNeighborsFraction is in [0,1], default .25. SelfAdjustmentWeight and SocialAdjustmentWeight are finite scalars, default 1.49 each. MaxIterations defaults to 200*nvars. MaxStallIterations is positive, default 20. FunctionTolerance is nonnegative, default 1e-6; a strict relative best-value change over the retained stall window triggers flag 1. Zero disables this strict function-change test.",
            "ObjectiveLimit defaults to -Inf and triggers flag -3 on a strictly lower actual best value. MaxTime and MaxStallTime default to Inf; nonnegative seconds or genuine scalar duration values are accepted. Finite limits require the original admitted Clock before effects. Limits are checked at generation boundaries and do not interrupt an in-flight callback. Flags -5 and -4 distinguish elapsed and no-improvement time; flag 0 is the iteration limit and -1 a logical observer stop.",
            "InitialPoints is an M-by-nvars double matrix or a scalar structure with X and optional Fval. A short population is filled; an oversized one uses its prefix. Supplied measurements are reused only for exactly unchanged supplied coordinates; clipping or a custom creation mismatch invalidates them. Missing measurement entries invoke the actual objective. InitialSwarm and InitialSwarmMatrix are legacy aliases of the same canonical InitialPoints identity. InitialSwarmSpan is a positive scalar or nvars-vector, default 2000, controlling one-sided/unbounded creation intervals and initial velocity ranges. Uniform creation uses both finite bounds as its interval.",
            "CreationFcn is pswcreationuniform or one actual handle called as swarm=f(problem). The dimension-resolved problem.options.SwarmSize is available. OutputFcn accepts handles/cells; PlotFcn accepts handles/cells or the real predefined pswplotbestf name. Both use stop=f(optimValues,state), with init/iter/done and funccount,bestx,bestfval,iteration,meanfval,stalliterations,swarm,swarmfvals. Every return must be logical scalar. A done stop is validated without relabeling completed termination. The current population shares authoritative Tensor backing; a retained predecessor triggers cooperative copy-on-write, not eager per-callback mirroring.",
            "UseParallel is off/auto/on; true maps to auto and false to off. UseVectorized=true has precedence, leaving parallel carriers inactive. Selected parallel execution uses the existing original-source CallbackBatch with bounded waves; there is no serial replay after partial acceptance or failure. Auto falls back only on known ineligibility or absent pool. On requires actual worker authority. HybridFcn is empty or fminsearch,fminunc,fmincon,patternsearch by name/selected handle, optionally paired with options in a cell. It runs only after flag 1. Bound problems require fmincon or patternsearch. The actual selected source is preserved, and a missing executable hybrid refuses before effects.",
            "Display is off/none/final/iter, default final; DisplayInterval is positive, default one. Creation truncation is reported in iterative display. Console/diary and plot operations use original authority. The helper plot has receiver-backed history and requires plot-core/UI; closing targets does not fabricate a replacement.",
        ]},
        BuiltinDocumentationSection{heading:"Execution boundary",paragraphs:&[
            "The host solver cooperates through scans, random proposals, objective and observer boundaries using the original CPU budget and cancellation authority. Random turns are short and never cross user code, so an objective can itself draw random values. output.rngstate records the default original stream before the algorithm; problem.rngstate restores through that same typed owner. No random stream is invented for deterministic reporting.",
            "Finite host-memory policies refuse before preparation, transfer, RNG, UI or objective effects because no complete resource bound exists for the full population/callback/hybrid workspace. Selected numeric options may use authenticated automatic-residency gathers; explicit resident controls and exact native-integer controls require their declared original-context RunMat extensions. Captures and inactive controls are not recursively gathered. Objective results require double class; automatic-residency results can be gathered, while explicit or unproven result placement requires explicit gather. No GPU-native algorithm or silent typed-integer problem-data overload is claimed.",
        ]},
    ],
    &[
        BuiltinExample{id:"actual-final-swarm",title:"Return actual final swarm values",program:"opts=optimoptions('particleswarm','Display','off','SwarmSize',4,'InitialPoints',[-1;0;1;2],'MaxIterations',0);\n[x,f,flag,out,points]=particleswarm(@(x)x(1)^2,1,-2,2,opts);",
            display_output:None,compatibility:BuiltinExampleCompatibility::Matlab,harness:BuiltinExampleHarness::Portable,fixture:BuiltinExampleFixture::None,requirements:BuiltinExampleRequirements::NONE,
            verification:BuiltinExampleVerification::Assertions{source:"assert(x==0 && f==0 && flag==0); assert(out.funccount==4); assert(isequal(points.X,[-1;0;1;2])); assert(isequal(points.Fval,[1;0;1;4]));"}},
        BuiltinExample{id:"vectorized-population",title:"Evaluate one vectorized generation",program:"opts=optimoptions('particleswarm','Display','off','SwarmSize',3,'InitialPoints',[-1 1;0 0;1 -1],'UseVectorized',true,'MaxIterations',0);\n[x,f,flag,out,points]=particleswarm(@(x)sum(x.^2,2),2,[-2 -2],[2 2],opts);",
            display_output:None,compatibility:BuiltinExampleCompatibility::Matlab,harness:BuiltinExampleHarness::Portable,fixture:BuiltinExampleFixture::None,requirements:BuiltinExampleRequirements::NONE,
            verification:BuiltinExampleVerification::Assertions{source:"assert(isequal(x,[0 0]) && f==0 && flag==0); assert(out.funccount==3); assert(isequal(points.Fval,[2;0;2]));"}},
    ]);
pub(super) const CREATION:BuiltinDocumentation=doc("pswcreationuniform",
    "Create the actual uniform initial particle positions without objective or velocity evaluation.",
    &[BuiltinDocumentationSection{heading:"Creation contract",paragraphs:&[
        "swarm=pswcreationuniform(problem) uses the documented particleswarm problem grammar. Only nvars, bounds, SwarmSize, InitialPoints.X and InitialSwarmSpan are active. It returns a SwarmSize-by-nvars host double matrix, retains supplied initial rows, and fills missing rows using the original random stream. It does not evaluate Fval, the objective, observers or hybrids, restore rngstate, or draw initial velocities. The particleswarm caller subsequently clips supplied coordinates and creates velocities.",
        "Both finite bounds define the uniform interval; a one-sided bound is an interval endpoint with InitialSwarmSpan width, and an unbounded component uses symmetric half-span endpoints. Default span is 2000. Nonrepresentable intervals fail truthfully. Finite host policies refuse before random work. Shared creation-control failures retain their canonical particleswarm identifier; helper grammar/output-count errors use the helper identifier. Original service failures are unchanged.",
    ]}],
    &[BuiltinExample{id:"supplied-prefix",title:"Preserve a complete supplied population",program:"p=struct('solver','particleswarm','objective',@(x)x(1)^2,'nvars',1,'lb',-3,'ub',3,'options',optimoptions('particleswarm','SwarmSize',3,'InitialPoints',[-1;0;2]));\ns=pswcreationuniform(p);",
        display_output:None,compatibility:BuiltinExampleCompatibility::Matlab,harness:BuiltinExampleHarness::Portable,fixture:BuiltinExampleFixture::None,requirements:BuiltinExampleRequirements::NONE,
        verification:BuiltinExampleVerification::Assertions{source:"assert(isequal(s,[-1;0;2]));"}}]);
pub(super) const PLOT:BuiltinDocumentation=doc("pswplotbestf",
    "Plot actual best particle fitness through the ordinary receiver-backed graphics owner.",
    &[BuiltinDocumentationSection{heading:"Two-argument plot callback",paragraphs:&[
        "stop=pswplotbestf(optimValues,state) reads only scalar double iteration and bestfval. state is init, iter or done; successful updates return logical false. init resets this helper's current-axes history; iter updates it; done retains the last scene without duplicate iteration samples. This is a real two-argument helper, not an alias that forwards three scalar-solver callback arguments.",
        "Only selected automatic-residency scalar metrics can gather. Captures and unrelated optimValues fields are not inspected. Explicit/unproven device placement, malformed scalars, unavailable plot-core/UI, finite host policy and retired receiver targets fail truthfully. Charts retain history in actual graphics scene payloads, not private solver population history.",
    ]}],
    &[BuiltinExample{id:"best-history",title:"Update the best-objective scene",program:"v=struct('iteration',0,'bestfval',4); stop=pswplotbestf(v,'init'); v.iteration=1; v.bestfval=1; pswplotbestf(v,'iter'); pswplotbestf(v,'done');",
        display_output:None,compatibility:BuiltinExampleCompatibility::Matlab,harness:BuiltinExampleHarness::BrowserGraphics,fixture:BuiltinExampleFixture::None,requirements:BuiltinExampleRequirements::NONE,
        verification:BuiltinExampleVerification::Assertions{source:"assert(islogical(stop) && ~stop);"}}]);
